using System.Globalization;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using FluentValidation;
using UrlShortener.Application.Repositories;
using UrlShortener.Domain;

namespace UrlShortener.Application.Links;

public sealed class LinkService(IValidator<CreateLinkRequest> validator, ILinkCreationRepository creation,
    IShortLinkRepository links, IRedirectStore redirects, ILinkStatsRepository stats,
    ICodeGenerator generator, TimeProvider clock)
{
    public async Task<ShortLink> CreateAsync(CreateLinkRequest request, string? key,
        IReadOnlyCollection<string> ownHosts, CancellationToken ct = default)
    {
        await validator.ValidateAndThrowAsync(request, ct);
        if (key is not null && (string.IsNullOrWhiteSpace(key) || key.Length > 128 || key.Any(char.IsControl)))
            throw new LinkOperationException(400, "Idempotency-Key must contain 1–128 non-control characters.");
        var target = new Uri(request.LongUrl);
        if (ownHosts.Any(host => string.Equals(host.TrimEnd('.'), target.IdnHost.TrimEnd('.'), StringComparison.OrdinalIgnoreCase)
            || (IsLoopbackHost(host) && target.IsLoopback)))
            throw new LinkOperationException(400, "The target URL cannot point to this service.");

        var hash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(request))));
        if (key is not null && await creation.FindByKeyAsync(key, ct) is { } previous)
        {
            if (previous.RequestHash != hash) throw new LinkOperationException(409, "Idempotency-Key was used with a different request.");
            return previous.Link;
        }

        var now = clock.GetUtcNow().UtcDateTime;
        if (request.ExpiresAt <= now) throw new LinkOperationException(400, "Expiry must be in the future.");
        var normalizedUrl = NormalizeUrl(request.LongUrl, target);
        // An initial attempt plus at most three collision retries.
        for (var attempt = 0; attempt <= 3; attempt++)
        {
            var code = request.CustomAlias ?? generator.Generate();
            if (request.CustomAlias is null && new[] { "api", "health", "swagger" }.Contains(code, StringComparer.OrdinalIgnoreCase)) continue;
            var result = await creation.TryCreateAsync(new ShortLink(code, normalizedUrl, now, request.ExpiresAt), key, hash, ct);
            if (result.Status is CreationStatus.Created or CreationStatus.Replayed) return result.Link!;
            if (result.Status == CreationStatus.KeyConflict) throw new LinkOperationException(409, "Idempotency-Key was used with a different request.");
            if (request.CustomAlias is not null) throw new LinkOperationException(409, "The custom alias is already taken.");
        }
        throw new LinkOperationException(503, "Unable to allocate a unique code. Please retry.");
    }

    /// <summary>
    /// Lowercases the URL scheme and host, removes the scheme's default port, and removes
    /// query parameters whose names start with <c>utm_</c> without regard to case. Other
    /// query parameter text and ordering, as well as the fragment, are preserved.
    /// </summary>
    private static string NormalizeUrl(string url, Uri parsed)
    {
        var separator = url.IndexOf("://", StringComparison.Ordinal);
        var schemeEnd = url.IndexOf(':');
        if (separator <= 0 || separator != schemeEnd
            || !(url.AsSpan(0, schemeEnd).Equals(Uri.UriSchemeHttp, StringComparison.OrdinalIgnoreCase)
                || url.AsSpan(0, schemeEnd).Equals(Uri.UriSchemeHttps, StringComparison.OrdinalIgnoreCase)))
            throw new ArgumentException("The URL must contain an absolute HTTP(S) scheme and authority.", nameof(url));

        var authorityStart = separator + 3;
        if (authorityStart >= url.Length)
            throw new ArgumentException("The URL must contain a non-empty authority.", nameof(url));

        var authorityEnd = url.IndexOfAny(['/','?', '#'], authorityStart);
        if (authorityEnd < 0) authorityEnd = url.Length;
        if (authorityEnd == authorityStart)
            throw new ArgumentException("The URL must contain a non-empty authority.", nameof(url));

        var authority = url.AsSpan(authorityStart, authorityEnd - authorityStart);
        var userInfoEnd = authority.LastIndexOf('@');
        var hostStart = userInfoEnd >= 0 ? userInfoEnd + 1 : 0;
        var hostEnd = authority.Length;
        var portStart = -1;

        if (hostStart < authority.Length && authority[hostStart] == '[')
        {
            var closingBracket = authority[hostStart..].IndexOf(']');
            if (closingBracket >= 0)
            {
                hostEnd = hostStart + closingBracket + 1;
                if (hostEnd < authority.Length && authority[hostEnd] == ':') portStart = hostEnd;
            }
        }
        else if (hostStart < authority.Length)
        {
            var colon = authority[hostStart..].LastIndexOf(':');
            if (colon >= 0)
            {
                portStart = hostStart + colon;
                hostEnd = portStart;
            }
        }

        var removePort = false;
        if (portStart >= 0 && int.TryParse(authority[(portStart + 1)..], NumberStyles.None,
                CultureInfo.InvariantCulture, out var port))
        {
            removePort = (parsed.Scheme.Equals(Uri.UriSchemeHttp, StringComparison.OrdinalIgnoreCase) && port == 80)
                || (parsed.Scheme.Equals(Uri.UriSchemeHttps, StringComparison.OrdinalIgnoreCase) && port == 443);
        }

        var builder = new StringBuilder(url.Length);
        builder.Append(url.AsSpan(0, schemeEnd).ToString().ToLowerInvariant());
        builder.Append("://");
        builder.Append(authority[..hostStart]);
        builder.Append(authority[hostStart..hostEnd].ToString().ToLowerInvariant());
        if (!removePort && portStart >= 0) builder.Append(authority[portStart..]);
        else if (portStart < 0) builder.Append(authority[hostEnd..]);
        builder.Append(url.AsSpan(authorityEnd));

        var normalizedAuthorityAndRemainder = builder.ToString();
        var queryStart = normalizedAuthorityAndRemainder.IndexOf('?', schemeEnd + 3);
        if (queryStart < 0) return normalizedAuthorityAndRemainder;

        var fragmentStart = normalizedAuthorityAndRemainder.IndexOf('#', queryStart + 1);
        var queryEnd = fragmentStart < 0 ? normalizedAuthorityAndRemainder.Length : fragmentStart;
        var query = normalizedAuthorityAndRemainder.AsSpan(queryStart + 1, queryEnd - queryStart - 1);
        if (query.IsEmpty)
            return string.Concat(normalizedAuthorityAndRemainder.AsSpan(0, queryStart),
                normalizedAuthorityAndRemainder.AsSpan(queryEnd));

        var retainedParameters = new List<string>();
        var queryText = query.ToString();
        foreach (var parameter in queryText.Split('&'))
        {
            var equals = parameter.IndexOf('=');
            var name = equals < 0 ? parameter : parameter[..equals];
            if (!name.StartsWith("utm_", StringComparison.OrdinalIgnoreCase))
                retainedParameters.Add(parameter);
        }

        if (retainedParameters.Count == 0)
            return string.Concat(normalizedAuthorityAndRemainder.AsSpan(0, queryStart),
                normalizedAuthorityAndRemainder.AsSpan(queryEnd));

        return string.Concat(normalizedAuthorityAndRemainder.AsSpan(0, queryStart + 1),
            string.Join('&', retainedParameters), normalizedAuthorityAndRemainder.AsSpan(queryEnd));
    }

    private static bool IsLoopbackHost(string host) => host.TrimEnd('.').Equals("localhost", StringComparison.OrdinalIgnoreCase)
        || (IPAddress.TryParse(host.Trim('[', ']'), out var address) && IPAddress.IsLoopback(address));

    public async Task<ShortLink> GetAsync(string code, CancellationToken ct = default) =>
        await links.FindByCodeAsync(code, ct) ?? throw new LinkOperationException(404, "Link not found.");

    public async Task<ShortLink> ResolveAsync(string code, CancellationToken ct = default)
    {
        var link = await redirects.FindAsync(code, ct) ?? throw new LinkOperationException(404, "Link not found.");
        if (!link.IsAvailableAt(clock.GetUtcNow().UtcDateTime)) throw new LinkOperationException(410, "Link has expired or is disabled.");
        return link;
    }

    public async Task DisableAsync(string code, CancellationToken ct = default)
    {
        if (!await redirects.DisableAsync(code, ct)) throw new LinkOperationException(404, "Link not found.");
    }

    public async Task<LinkStats> GetStatsAsync(string code, CancellationToken ct = default)
    {
        var link = await GetAsync(code, ct);
        return await stats.GetAsync(link.Id, ct);
    }
}

using FluentValidation;

namespace UrlShortener.Application.Links;

public sealed class CreateLinkValidator : AbstractValidator<CreateLinkRequest>
{
    public CreateLinkValidator()
    {
        RuleFor(x => x.LongUrl).Cascade(CascadeMode.Stop).NotEmpty().MaximumLength(2048)
            .Must(IsValidHttpUrl)
            .WithMessage("Only absolute HTTP or HTTPS URLs are accepted.");
        When(x => x.CustomAlias is not null, () =>
        {
            RuleFor(x => x.CustomAlias!).Cascade(CascadeMode.Stop).NotEmpty().Length(3, 30)
                .Matches(@"\A[A-Za-z0-9_-]+\z")
                .Must(alias => !new[] { "api", "health", "swagger" }.Contains(alias, StringComparer.OrdinalIgnoreCase))
                .WithMessage("The alias is reserved.");
        });
        RuleFor(x => x.ExpiresAt).Must(value => value is null || value.Value.Kind == DateTimeKind.Utc)
            .WithMessage("Expiry must use a UTC timestamp with a Z suffix.");
    }

    private static bool IsValidHttpUrl(string url)
    {
        if (url != url.Trim() || url.Any(char.IsControl)) return false;

        var separator = url.IndexOf("://", StringComparison.Ordinal);
        if (separator <= 0) return false;

        var scheme = url.AsSpan(0, separator);
        if (!(scheme.Equals(Uri.UriSchemeHttp, StringComparison.OrdinalIgnoreCase)
            || scheme.Equals(Uri.UriSchemeHttps, StringComparison.OrdinalIgnoreCase)))
            return false;

        return Uri.TryCreate(url, UriKind.Absolute, out var uri)
            && (uri.Scheme.Equals(Uri.UriSchemeHttp, StringComparison.OrdinalIgnoreCase)
                || uri.Scheme.Equals(Uri.UriSchemeHttps, StringComparison.OrdinalIgnoreCase))
            && !string.IsNullOrWhiteSpace(uri.Host);
    }
}
